import (
	"context"

	"github.com/JosePintos/tora/apps/api/internal/interfaces/graphql/model"
	"github.com/JosePintos/tora/apps/api/internal/user/application/commands"
)

// Login is the resolver for the login field.
func (r *mutationResolver) Login(ctx context.Context, input model.LoginInput) (*model.AuthPayload, error) {
	cmd := commands.LoginCommand{
		Username: input.Username,
		Password: input.Password,
	}

	token, err := r.Container.UserService.Login(
		ctx,
		cmd,
	)
	if err != nil {
		return nil, err
	}

	return &model.AuthPayload{
		Token: token,
	}, nil
}
